def _get(value,key,default=None):
 if isinstance(value,dict): return value.get(key,default)
 getter=getattr(value,"get",None)
 return getter(key,default) if callable(getter) else getattr(value,key,default)

def _plain(value):
 if isinstance(value,(list,tuple)): return [_plain(item) for item in value]
 if isinstance(value,dict) or hasattr(value,"items"):
  return {str(key):_plain(item) for key,item in value.items()}
 return value

def _seat(obs): return 1 if int(_get(obs,"player",0) or 0)==1 else 0

def _farm(obs,seat):
 farms=list(_get(obs,"farms",[]) or [])
 return farms[seat] if seat<len(farms) else {}

def _own_wheat_plants(obs):
 farm=_farm(obs,_seat(obs))
 total=0
 for row in list(_get(farm,"tiles",[]) or []):
  for tile in list(row or []):
   if _get(tile,"kind","")=="PLANT" and _get(tile,"crop","")=="WHEAT":
    total+=1
 return total

_YARN_REVERT={0:False,1:False}
_BRUNCH_REVERT={0:False,1:False}

def agent(obs,configuration=None):
 step=max(0,int(_get(obs,"step",0) or 0))
 shops=list(_get(_get(obs,"town",{}) or {},"unlocked_shops",[]) or [])
 seat=_seat(obs)
 if not shops:
  _YARN_REVERT[seat]=False
  _BRUNCH_REVERT[seat]=False
 if _YARN_REVERT[seat] or _BRUNCH_REVERT[seat]:
  return _V174_NS["agent"](obs)
 use_kaito=(step>=72 and shops and shops[0] in ('SMOOTHIE_SHOP', 'YARN_STORE', 'FARMERS_MARKET'))
 if step>=144 and len(shops)>=2 and tuple(shops[:2]) in (('PET_CAFE', 'YARN_STORE'), ('BRUNCH_SPOT', 'YARN_STORE')):
  use_kaito=True
 if use_kaito:
  kaito=_plain(_KAITO_NS["agent"](obs))
  if (shops and shops[0]=='YARN_STORE' and _own_wheat_plants(obs)<=8
      and _plain(_get(kaito,"farmer",[]))==["FEED"]
      and _plain(_get(kaito,"hands",[]))==[["PASS"],["SOUTH"],["PASS"]]
      and not list(_get(kaito,"market",[]) or [])):
   v174=_plain(_V174_NS["agent"](obs))
   if (_plain(_get(v174,"farmer",[]))==["FEED"]
       and _plain(_get(v174,"hands",[]))==[["PASS"],["SOUTH"],["PASS"]]
       and _plain(_get(v174,"market",[]))==[["BUY_PRODUCT","WHEAT",3],["BUY_PRODUCT","WHEAT",1]]):
    _YARN_REVERT[seat]=True
    return v174
  # In the audited Brunch-to-Yarn collision, the shared prefix reaches this
  # exact Wool/Cow fork with our farm liquid (>=365) but the similarly built
  # rival cash-starved (<=500).  V174's compatible suffix wins both seats.
  # All seven sampled strong-field states, including the old -54 sentinel
  # recovered by V197, lie outside this two-sided public liquidity regime.
  if (len(shops)>=2 and tuple(shops[:2])==('BRUNCH_SPOT','YARN_STORE')
      and float(_get(_farm(obs,seat),"money",0) or 0)>=365
      and float(_get(_farm(obs,1-seat),"money",0) or 0)<=500
      and _plain(_get(kaito,"farmer",[]))==["PLACE","FERTILIZER",2]
      and _plain(_get(kaito,"hands",[]))==[["NORTH"],["PASS"],["HARVEST"],["SOUTH"],["SOUTH"],["SOUTH"]]
      and _plain(_get(kaito,"market",[]))==[["SELL","WOOL",8],["BUY_ANIMAL","COW",2]]):
   v174=_plain(_V174_NS["agent"](obs))
   if (_plain(_get(v174,"farmer",[]))==["PLACE","FERTILIZER",2]
       and _plain(_get(v174,"hands",[]))==[["NORTH"],["PASS"],["HARVEST"],["SOUTH"],["SOUTH"],["SOUTH"]]
       and _plain(_get(v174,"market",[]))==[["SELL","WOOL",9],["BUY_ANIMAL","COW",2],["SELL","WOOL",1]]):
    _BRUNCH_REVERT[seat]=True
    return v174
  return kaito
 return _V174_NS["agent"](obs)
